/// Resolve a colour token id to its hex. Unknown id -> None: the painter skips the
/// primitive with a diagnostic (display.wit's fail-soft rule), never a guessed colour.
#[must_use]
pub fn color_hex(id: &str) -> Option<&'static str> {
    TOKEN_COLORS.binary_search_by(|&(k, _)| k.cmp(id)).ok().map(|i| TOKEN_COLORS[i].1)
}

/// Resolve a numeric token id (sizes, radii, spacing, stroke widths).
#[must_use]
pub fn number(id: &str) -> Option<f64> {
    TOKEN_NUMBERS.binary_search_by(|&(k, _)| k.cmp(id)).ok().map(|i| TOKEN_NUMBERS[i].1)
}

/// Resolve a colormap token id to its baked 256-entry LUT. Ids normalise by stripping
/// `colormap.` and folding `-`/`.` to `_` (colormap.inferno-class == inferno_class,
/// colormap.phosphor.cb == phosphor_cb) — the two spellings the bundle and the
/// manifests use for the same map.
#[must_use]
pub fn colormap_lut(id: &str) -> Option<&'static [u32]> {
    let slug = id.strip_prefix("colormap.").unwrap_or(id);
    let bytes = slug.as_bytes();
    let mut buf = [0u8; 64];
    if bytes.len() > buf.len() {
        return None;
    }
    for (i, &b) in bytes.iter().enumerate() {
        buf[i] = match b { b'-' | b'.' => b'_', c => c };
    }
    let norm = match std::str::from_utf8(&buf[..bytes.len()]) { Ok(s) => s, Err(_) => return None };
    match norm {
        "bipolar" => Some(COLORMAP_BIPOLAR_LUT),
        "bipolar_cb" => Some(COLORMAP_BIPOLAR_CB_LUT),
        "categorical_6" => Some(COLORMAP_CATEGORICAL_6_LUT),
        "categorical_6_cb" => Some(COLORMAP_CATEGORICAL_6_CB_LUT),
        "greyscale" => Some(COLORMAP_GREYSCALE_LUT),
        "inferno_class" => Some(COLORMAP_INFERNO_CLASS_LUT),
        "phosphor" => Some(COLORMAP_PHOSPHOR_LUT),
        "phosphor_cb" => Some(COLORMAP_PHOSPHOR_CB_LUT),
        "thermal" => Some(COLORMAP_THERMAL_LUT),
        _ => None,
    }
}
